# Load directions from config
DIRECTIONS = get_directions()
ALL_DIRECTIONS = get_all_directions()

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================

def adjacent_tiles(x, y):
    """Generate adjacent tiles in cardinal directions."""
    for dx, dy in DIRECTIONS:
        yield (x + dx, y + dy)

def manhattan_distance(pos1, pos2):
    """Calculate Manhattan distance between two positions."""
    return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

# =============================================================================
# PATHFINDING MODULE
# =============================================================================

class Pathfinder:
    """Handles pathfinding operations for entities."""
    
    def __init__(self):
        self.config = load_config()
    
    def bfs_path(self, start, target, is_valid_tile):
        """
        Compute shortest path from start to target using BFS.
        
        Args:
            start: Starting position (x, y)
            target: Target position (x, y)
            is_valid_tile: Function that returns True if a position is walkable
            
        Returns:
            List of positions representing the path, or empty list if no path found
        """
        if start == target:
            return [start]
            
        queue = deque([start])
        visited = set([start])
        prev = {start: None}
        
        while queue:
            current = queue.popleft()
            
            for neighbor in adjacent_tiles(*current):
                if neighbor not in visited and is_valid_tile(*neighbor):
                    visited.add(neighbor)
                    prev[neighbor] = current
                    queue.append(neighbor)
                    
                    if neighbor == target:
                        # Reconstruct path
                        path = []
                        pos = target
                        while pos is not None:
                            path.append(pos)
                            pos = prev[pos]
                        path.reverse()
                        return path
                        
        return []  # No path found
    
    def find_reachable_tiles(self, start, is_valid_tile, max_distance=None):
        """
        Find all reachable tiles within max_distance using BFS.
        
        Args:
            start: Starting position (x, y)
            is_valid_tile: Function that returns True if a position is walkable
            max_distance: Maximum distance to search (uses config default if None)
            
        Returns:
            List of reachable positions
        """
        if max_distance is None:
            max_distance = self.config["entities"]["adversary"]["pathfinding_max_distance_near"]
            
        queue = deque([(start, 0)])
        visited = set([start])
        reachable = []
        
        while queue:
            pos, dist = queue.popleft()
            if dist >= max_distance:
                continue
                
            reachable.append(pos)
            
            for neighbor in adjacent_tiles(*pos):
                if neighbor not in visited and is_valid_tile(*neighbor):
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
                    
        return reachable

# =============================================================================
# TERRAIN ANALYSIS MODULE
# =============================================================================

class TerrainAnalyzer:
    """Analyzes terrain features for AI decision making."""
    
    @staticmethod
    def is_hallway_tile(pos, is_valid_tile):
        """
        Check if a position is in a hallway (2+ walls adjacent).
        
        Args:
            pos: Position to check (x, y)
            is_valid_tile: Function that returns True if a position is walkable
            
        Returns:
            True if position appears to be in a hallway
        """
        x, y = pos
        wall_count = 0
        for neighbor in adjacent_tiles(x, y):
            if not is_valid_tile(*neighbor):
                wall_count += 1
        return wall_count >= 2
    
    @staticmethod
    def analyze_trail_freshness(tile, trail_set):
        """
        Calculate trail freshness score (lower = fresher).
        
        Args:
            tile: Position to analyze (x, y)
            trail_set: Set of trail positions
            
        Returns:
            Freshness score (lower is better)
        """
        if not trail_set:
            return 0
            
        # Simple heuristic: distance from trail centroid
        centroid_x = sum(t[0] for t in trail_set) / len(trail_set)
        centroid_y = sum(t[1] for t in trail_set) / len(trail_set)
        return manhattan_distance(tile, (centroid_x, centroid_y))

