class Entity:
    """Base class for all game entities."""
    
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.trail = set()
        self.trail.add((x, y))
        self.explored = set()
        self.explored.add((x, y))
        logging.debug(f"{self.__class__.__name__} created at ({x}, {y})")

    def move(self, *args, **kwargs):
        """Override in subclasses to implement movement behavior."""
        raise NotImplementedError("Subclasses must implement the move method.")

class Trap:
    """Represents a noise trap that can be triggered."""
    
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.triggered = False
        logging.debug(f"Trap created at ({x}, {y})")

    def trigger(self):
        """Trigger the trap."""
        self.triggered = True
        logging.debug(f"Trap at ({self.x}, {self.y}) triggered.")

    def is_visible(self, debug):
        """Check if trap should be visible to player."""
        return debug or self.triggered

