class Player(Entity):
    """Player character entity with health, speed, and vision attributes loaded from config."""
    
    def __init__(self, x, y):
        super().__init__(x, y)
        config = load_config()
        player_config = config["entities"]["player"]
        
        self.health = player_config["health"]
        self.speed = player_config["speed"]
        self.vision_radius = player_config["vision_radius"]
        self.max_health = player_config["max_health"]
        self.trail_order = [(x, y)]  # Ordered list of positions for adversary AI
        
        logging.debug(f"Player initialized at ({x}, {y}) with health={self.health}, speed={self.speed}, vision={self.vision_radius}")

    def move(self, dx, dy, game_map, is_open_tile):
        """
        Attempt to move player by given offset.
        
        Args:
            dx, dy: Movement offset
            game_map: Current game map
            is_open_tile: Function to check if a tile is walkable
            
        Returns:
            True if move was successful, False otherwise
        """
        nx, ny = self.x + dx, self.y + dy
        if is_open_tile(game_map, nx, ny):
            self.x, self.y = nx, ny
            self.trail.add((self.x, self.y))
            self.explored.add((self.x, self.y))
            if (self.x, self.y) not in self.trail_order:
                self.trail_order.append((self.x, self.y))
            logging.debug(f"Player moved to ({self.x}, {self.y})")
            return True
        return False

    def take_damage(self, amount):
        """
        Apply damage to player.
        
        Args:
            amount: Damage amount
            
        Returns:
            True if player is still alive, False otherwise
        """
        self.health -= amount
        logging.debug(f"Player took {amount} damage, health now {self.health}")
        return self.health > 0

    def heal(self, amount):
        """
        Heal player by given amount (capped at max_health from config).
        
        Args:
            amount: Healing amount
        """
        self.health = min(self.health + amount, self.max_health)
        logging.debug(f"Player healed by {amount}, health now {self.health}")

