class AdversaryBehavior:
    """Handles different adversary behavior modes."""
    
    def __init__(self, adversary):
        self.adversary = adversary
        self.pathfinder = Pathfinder()
        self.terrain = TerrainAnalyzer()
        self.config = load_config()
    
    def follow_cached_path(self, game, is_floor):
        """Follow a previously computed path if still valid."""
        if not self.adversary.cached_path:
            return False
            
        # Check if path is still valid
        if self.adversary.path_target and not is_floor(game.map, *self.adversary.path_target):
            self.adversary.cached_path = []
            self.adversary.path_target = None
            return False
            
        next_pos = self.adversary.cached_path[0]
        if is_floor(game.map, *next_pos):
            self.adversary.cached_path.pop(0)
            self.adversary.move_to(*next_pos)
            
            # Clear path when reached target
            if not self.adversary.cached_path:
                self.adversary.path_target = None
                
            return True
        else:
            # Path blocked, clear cache
            self.adversary.cached_path = []
            self.adversary.path_target = None
            return False
    
    def pursue_alerted_position(self, game, is_floor):
        """Pursue alerted player position using cached pathfinding."""
        target = self.adversary.alerted_player_pos
        if (self.adversary.x, self.adversary.y) == target:
            self.adversary.alerted_player_pos = None
            self.adversary.cached_path = []
            self.adversary.path_target = None
            logging.debug("Adversary arrived at alerted player position.")
            return False
            
        # Use cached path if target hasn't changed
        if self.adversary.path_target == target and self.adversary.cached_path:
            return self.follow_cached_path(game, is_floor)
            
        # Compute new path
        path = self.pathfinder.bfs_path(
            (self.adversary.x, self.adversary.y), 
            target, 
            lambda x, y: is_floor(game.map, x, y)
        )
        if path and len(path) > 1:
            self.adversary.cached_path = path[1:]  # Exclude current position
            self.adversary.path_target = target
            self.adversary.move_to(*path[1])
            self.adversary.mode = "alerted_player_seek"
            logging.debug(f"Adversary computed path to alerted position, moving to {path[1]}")
            return True
        else:
            self.adversary.alerted_player_pos = None
            return False
    
    def smart_trail_walk(self, game, player_trail, is_floor):
        """Intelligently follow player trail in chronological order."""
        if not player_trail:
            return False
            
        # Check if we can see any trail tiles
        visible_trail = []
        for tile in self.adversary.tiles_in_vision():
            if tile in player_trail and is_floor(game.map, *tile):
                visible_trail.append(tile)
                
        if not visible_trail:
            return False
            
        # If we're not on a trail tile, move to the nearest one
        current_pos = (self.adversary.x, self.adversary.y)
        if current_pos not in player_trail:
            return self._approach_trail(game, visible_trail, is_floor)
            
        # We're on a trail tile - follow it systematically
        return self._continue_trail_walk(game, player_trail, is_floor)
    
    def _approach_trail(self, game, visible_trail, is_floor):
        """Move towards the nearest visible trail tile."""
        current_pos = (self.adversary.x, self.adversary.y)
        nearest_trail = min(visible_trail, key=lambda t: manhattan_distance(current_pos, t))
        path = self.pathfinder.bfs_path(
            current_pos, 
            nearest_trail, 
            lambda x, y: is_floor(game.map, x, y)
        )
        if path and len(path) > 1:
            self.adversary.cached_path = path[1:]
            self.adversary.path_target = nearest_trail
            self.adversary.move_to(*path[1])
            self.adversary.mode = "trail_approach"
            logging.debug(f"Adversary approaching trail at {nearest_trail}")
            return True
        return False
    
    def _continue_trail_walk(self, game, player_trail, is_floor):
        """Continue walking on trail from current position."""
        # Look for adjacent trail tiles we haven't explored
        unexplored_trail = []
        explored_trail = []
        
        for neighbor in adjacent_tiles(self.adversary.x, self.adversary.y):
            if neighbor in player_trail and is_floor(game.map, *neighbor):
                if neighbor not in self.adversary.explored:
                    unexplored_trail.append(neighbor)
                else:
                    explored_trail.append(neighbor)
                    
        # Prefer unexplored trail tiles
        if unexplored_trail:
            best_tile = min(unexplored_trail, 
                          key=lambda t: self.terrain.analyze_trail_freshness(t, player_trail))
            self.adversary.move_to(*best_tile)
            self.adversary.mode = "trail_walk"
            logging.debug(f"Adversary following fresh trail to {best_tile}")
            return True
            
        # If all adjacent trail is explored, move to explored trail tiles
        if explored_trail:
            next_tile = random.choice(explored_trail)
            self.adversary.move_to(*next_tile)
            self.adversary.mode = "trail_walk"
            logging.debug(f"Adversary continuing on explored trail to {next_tile}")
            return True
            
        return False
    
    def systematic_exploration(self, game, is_floor):
        """Explore systematically, prioritizing hallways and unexplored areas."""
        config = self.config["entities"]["adversary"]
        
        # Look for unexplored tiles in order of preference
        targets = []
        
        # First priority: unexplored hallway tiles
        nearby_tiles = self.pathfinder.find_reachable_tiles(
            (self.adversary.x, self.adversary.y),
            lambda x, y: is_floor(game.map, x, y),
            max_distance=config["pathfinding_max_distance_near"]
        )
        
        for tile in nearby_tiles:
            if tile not in self.adversary.explored and self.terrain.is_hallway_tile(
                tile, lambda x, y: is_floor(game.map, x, y)
            ):
                targets.append((tile, 1))  # High priority
                
        # Second priority: any unexplored tiles
        if not targets:
            for tile in self.pathfinder.find_reachable_tiles(
                (self.adversary.x, self.adversary.y),
                lambda x, y: is_floor(game.map, x, y),
                max_distance=config["pathfinding_max_distance_far"]
            ):
                if tile not in self.adversary.explored:
                    targets.append((tile, 2))  # Medium priority
                    
        if not targets:
            return False
            
        # Choose closest target of highest priority
        targets.sort(key=lambda x: (x[1], manhattan_distance((self.adversary.x, self.adversary.y), x[0])))
        target_tile = targets[0][0]
        
        # Compute path to target
        path = self.pathfinder.bfs_path(
            (self.adversary.x, self.adversary.y),
            target_tile,
            lambda x, y: is_floor(game.map, x, y)
        )
        if path and len(path) > 1:
            self.adversary.cached_path = path[1:]
            self.adversary.path_target = target_tile
            self.adversary.move_to(*path[1])
            self.adversary.mode = "systematic_explore"
            logging.debug(f"Adversary exploring systematically toward {target_tile}")
            return True
            
        return False
    
    def step_randomly(self, game, is_floor):
        """Move randomly to a valid adjacent tile."""
        neighbors = [n for n in adjacent_tiles(self.adversary.x, self.adversary.y) 
                    if is_floor(game.map, *n)]
        if not neighbors:
            logging.debug("Adversary is trapped, no valid moves.")
            return
            
        # Prefer unexplored tiles
        unexplored = [n for n in neighbors if n not in self.adversary.explored]
        if unexplored:
            chosen = random.choice(unexplored)
        else:
            chosen = random.choice(neighbors)
            
        self.adversary.move_to(*chosen)
        self.adversary.mode = "explore"
        logging.debug(f"Adversary moved randomly to {chosen}")

