class AdversaryBase(Entity):
    """Base class for adversary entities with vision and basic state."""
    
    def __init__(self, x, y):
        super().__init__(x, y)
        config = load_config()
        adversary_config = config["entities"]["adversary"]
        
        self.mode = "explore"
        self.last_dir = (0, 0)
        self.in_hallway = False
        self.vision_radius = adversary_config["vision_radius"]
        self.alerted_player_pos = None
        logging.debug(f"AdversaryBase initialized at ({x}, {y}) with vision={self.vision_radius}")

    def move(self, *args, **kwargs):
        """Override in subclasses to implement movement behavior."""
        raise NotImplementedError("AdversaryBase is abstract.")

    def tiles_in_vision(self):
        """Generate all tiles within vision radius."""
        for dx in range(-self.vision_radius, self.vision_radius + 1):
            for dy in range(-self.vision_radius, self.vision_radius + 1):
                yield (self.x + dx, self.y + dy)

    def can_see_player(self, player_pos, game_map, is_floor):
        """Check if adversary can see the player."""
        px, py = player_pos
        for dx in range(-self.vision_radius, self.vision_radius + 1):
            for dy in range(-self.vision_radius, self.vision_radius + 1):
                tx, ty = self.x + dx, self.y + dy
                if (tx, ty) == (px, py):
                    return True
        return False

class Adversary(AdversaryBase):
    """
    Main adversary class with intelligent pathfinding and behavior.
    
    Uses composition pattern with AdversaryBehavior for clean separation of concerns.
    """

    def __init__(self, x, y):
        super().__init__(x, y)
        self.trail_direction = None
        self.cached_path = []  # Current path being followed
        self.path_target = None  # Target position for current path
        self.trail_sequence = []  # Ordered sequence for trail following
        self.trail_index = 0  # Current position in trail sequence
        self.behavior = AdversaryBehavior(self)

    def alert_to_player_position(self, pos):
        """Alert adversary to player's position."""
        self.alerted_player_pos = pos
        self.cached_path = []  # Clear cached path when alerted
        self.path_target = None
        logging.debug(f"Adversary alerted to player position at {pos}")

    def move(self, game, player_trail, player_pos, is_floor, add_message):
        """
        Main movement logic using behavior delegation.
        
        Priority order:
        1. Follow cached path if available
        2. Pursue alerted player position
        3. Walk player trail intelligently
        4. Explore systematically
        5. Move randomly as fallback
        """
        logging.debug(f"Adversary move called at ({self.x}, {self.y})")
        
        # Priority 1: Follow cached path if available and valid
        if self.behavior.follow_cached_path(game, is_floor):
            logging.debug("Adversary following cached path.")
            return
            
        # Priority 2: Pursue alerted player position
        if self.alerted_player_pos is not None:
            if self.behavior.pursue_alerted_position(game, is_floor):
                logging.debug("Adversary pursuing alerted player position.")
                return
        
        # Priority 3: Walk player trail intelligently
        if self.behavior.smart_trail_walk(game, player_trail, is_floor):
            logging.debug("Adversary walking player trail.")
            return
            
        # Priority 4: Explore systematically
        if self.behavior.systematic_exploration(game, is_floor):
            logging.debug("Adversary exploring systematically.")
            return
            
        # Fallback: Random movement
        self.behavior.step_randomly(game, is_floor)
        logging.debug("Adversary stepped randomly.")

    def move_to(self, x, y):
        """Move to a specific position and update state."""
        self.last_dir = (x - self.x, y - self.y)
        self.x, self.y = x, y
        self.trail.add((x, y))
        self.explored.add((x, y))
        logging.debug(f"Adversary moved to ({x}, {y})")

    def direction_from_player(self, player_pos):
        """Calculate direction from player for UI display."""
        dx = self.x - player_pos[0]
        dy = self.y - player_pos[1]
        if dx == 0 and dy == 0:
            return None
        if abs(dx) > abs(dy):
            if dx > 0:
                return 'E' if dy == 0 else ('NE' if dy < 0 else 'SE')
            else:
                return 'W' if dy == 0 else ('NW' if dy < 0 else 'SW')
        else:
            if dy > 0:
                return 'S' if dx == 0 else ('SE' if dx > 0 else 'SW')
            else:
                return 'N' if dx == 0 else ('NE' if dx > 0 else 'NW')